import random

def first_fit(items, capacity):
    bins = []
    for item in items:
        placed = False
        for i in range(len(bins)):
            if bins[i] + item <= capacity:
                bins[i] += item
                placed = True
                break
        if not placed:
            bins.append(item)
    return bins

def test_first_fit_property(n_trials=10000):
    for _ in range(n_trials):
        d = random.randint(1, 200)
        items = [random.random() for _ in range(d)]
        capacity = 1.0
        bins = first_fit(items, capacity)
        for i in range(len(bins)):
            for j in range(i + 1, len(bins)):
                if bins[i] + bins[j] <= 1.0000000001:
                    return False, items, bins, i, j
    return True, None, None, None, None

result, items, bins, i, j = test_first_fit_property()
print(f"Property holds: {result}")
if not result:
