    print(f"Bins: {bins}")
    print(f"Bins {i} and {j} sum to {bins[i] + bins[j]}")

import itertools

def get_opt(items, capacity=1.0):
    # Bin packing is NP-hard, but for small d we can use brute force
    d = len(items)
    for k in range(1, d + 1):
        # Try all possible partitions of d items into k bins
        # This is too slow. Let's use a simpler approach.
        if can_pack(items, k, capacity):
            return k
    return d

def can_pack(items, k, capacity):
    # Try to pack items into k bins
    bins = [0.0] * k
    def backtrack(item_idx):
        if item_idx == len(items):
            return True
        for b in range(k):
            if bins[b] + items[item_idx] <= capacity + 1e-9:
                bins[b] += items[item_idx]
                if backtrack(item_idx + 1):
                    return True
                bins[b] -= items[item_idx]
        return False
    return backtrack(0)

def find_max_opt(S, max_d=10):
    max_opt = 0
    # We need to sample sets of items that sum to S.
    # This is hard. Let's try items of the same size.
    for d in range(1, max_d + 1):
        a = S / d
        if a <= 1.0:
            opt = get_opt([a] * d)
            max_opt = max(max_opt, opt)
    return max_opt

for s in range(1, 6):
    print(f"S={s}, max_opt={find_max_opt(s)}")

